module asyn_fifo #(
    parameter	WIDTH = 8,
    parameter 	DEPTH = 16,
    parameter ADDR_WIDTH = $clog2(DEPTH)
) (
    input 					wclk,
    input 					rclk,
    input 					wrstn,
    input					rrstn,
    input 					winc,
    input 			 		rinc,
    input 		[WIDTH-1:0]	wdata,
    output reg wfull,
    output reg rempty,
    output reg [WIDTH-1:0]	rdata
);

reg [ADDR_WIDTH-1:0] waddr;
reg [ADDR_WIDTH-1:0] raddr;
reg [WIDTH-1:0] mem [0:DEPTH-1];
wire [ADDR_WIDTH-1:0] waddr_next;
wire [ADDR_WIDTH-1:0] raddr_next;

assign waddr_next = (waddr == DEPTH-1) ? 0 : waddr + 1;
assign raddr_next = (raddr == DEPTH-1) ? 0 : raddr + 1;

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        waddr <= 0;
        wfull <= 0;
    end else begin
        if (winc && !rempty) begin
            mem[waddr] <= wdata;
            waddr <= waddr_next;
            wfull <= (waddr == raddr);
        end
    end
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        raddr <= 0;
        rempty <= 1;
    end else begin
        if (rinc && !wfull) begin
            rdata <= mem[raddr];
            raddr <= raddr_next;
            rempty <= (waddr == raddr);
        end
    end
end

endmodule

module dual_port_RAM #(
    parameter DEPTH = 16,
    parameter WIDTH = 8
) (
    input wclk,
    input wenc,
    input [$clog2(DEPTH)-1:0] waddr,
    input [WIDTH-1:0] wdata,
    input rclk,
    input renc,
    input [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);

reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

always @(posedge wclk) begin
    if (wenc)
        RAM_MEM[waddr] <= wdata;
end

always @(posedge rclk) begin
    if (renc)
        rdata <= RAM_MEM[raddr];
end

endmodule
